def fires(b):
    return len(b.their_playable_wins) >= 1

def level(b):
    n = len(b.their_playable_wins)
    t = min(len(b.their_wins), 4)
    return min(9, 3 * n + t)

def _w(b):
    t = set(b.their_wins) | set(b.my_wins)
    s = 0
    if (0, 1) in t and (0, 5) in t:
        s += 4
    for r in range(1, 6):
        if (r, 4) in t:
            s += 2
    if len(b.their_playable_wins) >= 1:
        s += 1
    return s

def fires(b):
    return _w(b) >= 3

def level(b):
    return min(9, _w(b) * 2)

def _bottom(b):
    g = b.grid
    if g[0][1] != 0 or g[0][5] != 0:
        return 0
    a = g[0][2]
    if a == 0 or g[0][4] != a:
        return 0
    if g[0][3] == a:
        return 3
    if g[0][3] == 0:
        return 2
    return 0

def _w(b):
    s = 2 * _bottom(b)
    if len(b.their_playable_wins) >= 2:
        s += 3
    elif len(b.their_playable_wins) == 1:
        s += 1
    return s

def fires(b):
    return _w(b) >= 3

def level(b):
    return min(9, _w(b) + 1 if _w(b) else 0)

def _bottom(b):
    g = b.grid
    if g[0][1] != 0 or g[0][5] != 0:
        return 0
    a = g[0][2]
    if a == 0 or g[0][4] != a or g[0][3] not in (0, a):
        return 0
    return 1

def _late(b):
    h = b.heights
    if h[4] > 3:
        return 0
    full = sum(1 for c in (0, 1, 2, 5, 6) if h[c] >= 5)
    s = full
    t = set(b.their_wins) | set(b.my_wins)
    s += sum(1 for r in range(h[4], 6) if (r, 4) in t)
    return s

def _w(b):
    s = _late(b)
    if _bottom(b):
        s += 5
    if len(b.their_playable_wins) >= 2:
        s += 2
    return s

def fires(b):
    return _w(b) >= 5

def level(b):
    return min(9, _w(b))
